#!/bin/sh
# Method for 2026-09-23-003-re-arm-cadence-normal-30min-vs-storm-5s-from-session-cc47a367.md -- re-runnable, and fair game to improve in place
# (unlike the capture, which is append-only).
'bash' '-c' $'\n    echo \'--- timestamps of every Monitor re-arm tool_use call in this transcript ---\'\n    grep -o \'"timestamp":"[^"]*".*"name":"Monitor"\' \'/home/bukzor/.claude/projects/-home-bukzor-claude-mitmproxy/cc47a367-0d82-4ee1-a67f-4c9d4e4c169e.jsonl\' | grep -o \'"timestamp":"[^"]*"\' | sort | uniq -c | tail -1\n    grep -o \'"type":"assistant"[^}]*\' \'/home/bukzor/.claude/projects/-home-bukzor-claude-mitmproxy/cc47a367-0d82-4ee1-a67f-4c9d4e4c169e.jsonl\' > /dev/null\n    python3 -c "\nimport json\nf = \'/home/bukzor/.claude/projects/-home-bukzor-claude-mitmproxy/cc47a367-0d82-4ee1-a67f-4c9d4e4c169e.jsonl\'\ntss = []\nfor line in open(f, errors=\'replace\'):\n    if \'\\"name\\":\\"Monitor\\"\' not in line:\n        continue\n    try:\n        d = json.loads(line)\n    except Exception:\n        continue\n    content = d.get(\'message\', {}).get(\'content\')\n    if not isinstance(content, list):\n        continue\n    for c in content:\n        if isinstance(c, dict) and c.get(\'type\')==\'tool_use\' and c.get(\'name\')==\'Monitor\':\n            if \'driftwatch\' in json.dumps(c.get(\'input\', {})):\n                tss.append(d.get(\'timestamp\'))\nprint(\'total re-arm calls in this session:\', len(tss))\nprint(\'first:\', tss[0])\nprint(\'last:\', tss[-1])\n# print gaps\nimport datetime as dt\ndef parse(s): return dt.datetime.strptime(s, \'%Y-%m-%dT%H:%M:%S.%fZ\')\ngaps = [(parse(b)-parse(a)).total_seconds() for a,b in zip(tss, tss[1:])]\nprint(\'gap seconds: min\', min(gaps), \'max\', max(gaps))\n# show distribution: how many gaps < 10s vs > 600s\nunder10 = sum(1 for g in gaps if g < 10)\nover600 = sum(1 for g in gaps if g > 600)\nprint(\'gaps <10s (storm-like):\', under10)\nprint(\'gaps >600s (normal 30min-cap cadence):\', over600)\n# when did it first drop under 10s?\nfor a,b,g in zip(tss, tss[1:], gaps):\n    if g < 10:\n        print(\'first sub-10s gap:\', a, \'->\', b, g, \'seconds\')\n        break\n"\n  '
